namespace AkilliKisayol {
 public static class ModernTests {
  static string Reply(){return LocalLlm.Json().Serialize(new{status="ready",name="Copy",trigger="F8",app_id="global",message="",notes=new string[0],steps=new[]{new{kind="copy",combo="",text="",ms=0}}});}
  public static void Unit(Action<bool,string> check){
   var options=new ModelOptions{Remote=true,Model="my-custom-model",Endpoint="http://localhost:1234/v1"};check(options.BaseUri().AbsoluteUri=="http://localhost:1234/v1/"&&options.Validate("")==null,"Custom model and API base URL are accepted without provider or model allowlists");options.ApiKey="fixture-secret";check(options.ApiKey=="fixture-secret"&&!options.ProtectedKey.Contains("fixture-secret"),"API credentials are encrypted for the current Windows user");
   var request=new LlmRequest{Prompt="When I press F8, copy",Applications=new List<string>(),Options=options};var payload=(Dictionary<string,object>)LlmProtocol.CreatePayload(request);check((string)payload["model"]=="my-custom-model"&&!payload.ContainsKey("chat_template_kwargs")&&!payload.ContainsKey("reasoning_effort")&&!payload.ContainsKey("cache_prompt"),"Remote requests contain the user's model ID and no local model-specific parameters");
   options.StructuredOutput=false;payload=(Dictionary<string,object>)LlmProtocol.CreatePayload(request);check(!payload.ContainsKey("response_format")&&LocalLlm.Json().Serialize(payload).Contains("Output JSON schema"),"Servers without response_format still receive the full output contract");check(LlmProtocol.ReadPlan("```json\n"+Reply()+"\n```",request).Ready&&LlmProtocol.ReadPlan("<think>reasoning</think>\n"+Reply(),request).Ready,"Valid fenced JSON and reasoning prefixes from other model families are supported");
   options.Endpoint="file:///C:/model";check(options.Validate("")!=null,"Non-HTTP API addresses are rejected");options.Endpoint="http://localhost:1234/v1/?api_key=secret";check(options.Validate("")!=null,"API base URLs cannot accidentally embed query credentials");options.Endpoint="http://localhost:1234/v1/";
   string folder=Path.Combine(Path.GetTempPath(),"MakroPlus-model-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{var state=new State{ModelPath=@"Z:\custom\chosen.gguf",ModelOptions=options,StepIntervalMs=50};string file=Path.Combine(folder,"settings.json");Storage.Write(state,file);var loaded=Storage.Read(file);check(loaded.ModelPath==state.ModelPath&&loaded.ModelOptions.Model==options.Model&&loaded.ModelOptions.ApiKey=="fixture-secret"&&loaded.StepIntervalMs==50,"Model selection, API configuration and playback speed survive persistence without silently changing the model");Transfer.Export(state,file);var exported=Storage.Read(file);check(string.IsNullOrEmpty(exported.ModelOptions.ProtectedKey)&&state.ModelOptions.ApiKey=="fixture-secret","Export excludes API credentials without changing saved credentials");var imported=Transfer.Import(new State(),loaded,new Dictionary<string,string>(),false);check(imported.State.ModelOptions.Model==options.Model&&imported.State.ModelOptions.ProtectedKey==null&&imported.State.StepIntervalMs==50,"Import carries provider and speed preferences without transferring secrets");check(ModelFiles.Resolve("",folder,folder)==""&&ModelFiles.Resolve(@"Z:\absent.gguf",folder,folder)==@"Z:\absent.gguf","No fixed download path or unrelated fallback model is selected");}finally{Directory.Delete(folder,true);}
   int savedSpeed=Actions.StepIntervalMs;try{Actions.StepIntervalMs=100;var watch=Stopwatch.StartNew();Actions.RunSteps(new Binding{Steps=Enumerable.Range(0,10).Select(i=>new ActionStep{Kind="Wait",Delay=10}).ToList()},IntPtr.Zero).GetAwaiter().GetResult();watch.Stop();check(watch.ElapsedMilliseconds>=90&&watch.ElapsedMilliseconds<700,"Explicit waits run for their requested duration without redundant automatic or final-step delays");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"execution-timing.json"),LocalLlm.Json().Serialize(new{requestedWaitMilliseconds=100,actualMilliseconds=watch.ElapsedMilliseconds,steps=10,configuredInterStepMilliseconds=100}));}finally{Actions.StepIntervalMs=savedSpeed;}
   Server(check);
  }
  static void Server(Action<bool,string> check){
   var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var requests=new List<string>();var server=Task.Run(()=>{for(int attempt=0;attempt<2;attempt++)using(var client=listener.AcceptTcpClient()){client.ReceiveTimeout=10000;client.SendTimeout=10000;using(var stream=client.GetStream()){var buffer=new List<byte>();int end=-1;while(end<0){int value=stream.ReadByte();if(value<0)throw new IOException("Incomplete fixture request");buffer.Add((byte)value);int n=buffer.Count;if(n>=4&&buffer[n-4]==13&&buffer[n-3]==10&&buffer[n-2]==13&&buffer[n-1]==10)end=n;if(n>32768)throw new IOException("Oversized fixture headers");}string headers=Encoding.ASCII.GetString(buffer.ToArray());int length=int.Parse(headers.Split(new[]{"\r\n"},StringSplitOptions.None).First(x=>x.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase)).Split(':')[1]);if(headers.IndexOf("100-continue",StringComparison.OrdinalIgnoreCase)>=0){byte[] interim=Encoding.ASCII.GetBytes("HTTP/1.1 100 Continue\r\n\r\n");stream.Write(interim,0,interim.Length);}var body=new byte[length];for(int offset=0;offset<length;){int read=stream.Read(body,offset,length-offset);if(read==0)throw new IOException("Incomplete fixture body");offset+=read;}requests.Add(headers+Encoding.UTF8.GetString(body));string completion=LocalLlm.Json().Serialize(new{choices=new[]{new{finish_reason="stop",message=new{content=attempt==0?"invalid json":"```json\n"+Reply()+"\n```"}}}});byte[] bytes=Encoding.UTF8.GetBytes(completion);byte[] head=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\n\r\n");stream.Write(head,0,head.Length);stream.Write(bytes,0,bytes.Length);}}});
   try{var options=new ModelOptions{Remote=true,Model="fixture/any-family",Endpoint="http://127.0.0.1:"+port+"/v1/",StructuredOutput=false};options.ApiKey="fixture-key";using(var model=new LocalLlm())using(var timeout=new CancellationTokenSource(15000)){var plan=model.AnalyzeAsync(new LlmRequest{Prompt="When I press F8, copy",Applications=new List<string>(),Options=options},p=>{},timeout.Token).GetAwaiter().GetResult();server.GetAwaiter().GetResult();check(plan.Ready&&plan.Binding.Steps.Single().Key==67&&requests.Count==2&&model.StartupCount==0,"Actual HTTP provider validates, repairs once and returns an executable plan without a local model");check(requests.All(r=>r.Contains("POST /v1/chat/completions")&&r.Contains("Bearer fixture-key")&&r.Contains("fixture/any-family")),"Custom endpoint path, authentication and model ID reach the configured server");}}finally{listener.Stop();}
  }
  public static void Ui(MainWindow owner,Action<bool,string> check,Action<Window,string> screenshot){
   owner.ProductViewForTest("AI model");screenshot(owner,"model-settings-page.png");var dialog=new ModelSettingsWindow(new ModelOptions(),""){Owner=owner};dialog.Show();check(dialog.IsVisible,"Model configuration opens with no bundled or selected model");screenshot(dialog,"model-settings-dialog.png");dialog.Close();Theme.Apply(false);owner.ProductViewForTest("Home");screenshot(owner,"makroplus-2.2-light.png");Theme.Apply(true);owner.ProductViewForTest("Home");screenshot(owner,"makroplus-2.2-dark.png");check(((System.Windows.Media.SolidColorBrush)Application.Current.Resources["Accent"]).Color.R==255,"Dark theme applies the coral accent palette");
  }
  public static int Real(){
   var results=new List<object>();string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"custom-model-test.json");
   using(var client=new HttpClient(new HttpClientHandler{UseProxy=false}){Timeout=TimeSpan.FromSeconds(2)})using(var job=new ProcessJob())using(var process=new Process())try{
    string modelPath=Storage.Read(Storage.FilePath).ModelPath;if(!File.Exists(modelPath))throw new FileNotFoundException("Select a local test model first.");var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();string credential=Guid.NewGuid().ToString("N");process.StartInfo=new ProcessStartInfo(LocalLlm.FindRuntime()){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true,Arguments="--model "+LocalLlm.Quote(modelPath)+" --alias user-selected-model --host 127.0.0.1 --port "+port+" --ctx-size 8192 --parallel 1 --gpu-layers auto --reasoning off --jinja --no-webui --no-agent"};process.StartInfo.EnvironmentVariables["LLAMA_API_KEY"]=credential;process.OutputDataReceived+=(s,e)=>{};process.ErrorDataReceived+=(s,e)=>{};process.Start();job.Assign(process);process.BeginOutputReadLine();process.BeginErrorReadLine();client.DefaultRequestHeaders.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",credential);var deadline=DateTime.UtcNow.AddMinutes(3);while(true){if(process.HasExited)throw new Exception("Fixture model server exited.");try{using(var response=client.GetAsync("http://127.0.0.1:"+port+"/health").GetAwaiter().GetResult())if(response.IsSuccessStatusCode)break;}catch(HttpRequestException){}catch(TaskCanceledException){}if(DateTime.UtcNow>deadline)throw new TimeoutException("Fixture model server startup timed out.");Thread.Sleep(100);}
    var options=new ModelOptions{Remote=true,Endpoint="http://127.0.0.1:"+port+"/v1/",Model="user-selected-model"};options.ApiKey=credential;
    using(var model=new LocalLlm())for(int i=0;i<3;i++){options.StructuredOutput=i==0;var watch=Stopwatch.StartNew();var plan=model.AnalyzeAsync(new LlmRequest{Prompt=i==0?"When I press F8, select all text and copy it.":i==1?"Assign F9 to type \"Custom model\", wait 100 ms, and press Enter.":"Press Ctrl+S.",Gesture=i==2?GesturePromptTests.Shape():null,Applications=new List<string>(),Options=options.Copy()},p=>{},CancellationToken.None).GetAwaiter().GetResult();bool valid=plan.Ready&&(i==0?plan.Binding.Steps.Count==2&&plan.Binding.Steps[0].Key==65&&plan.Binding.Steps[1].Key==67:i==1?plan.Binding.Steps.Count==3&&plan.Binding.Steps[0].Text=="Custom model"&&plan.Binding.Steps[1].Delay==100&&plan.Binding.Steps[2].Key==13:plan.Binding.Gesture!=null&&plan.Binding.Key==0&&plan.Binding.Steps.Count==1&&plan.Binding.Steps[0].Key==83&&plan.Binding.Steps[0].Mods==2);results.Add(new{scenario=i==0?"Custom API model with structured JSON":i==1?"Custom API model without response_format":"Touchpad action through custom API",passed=valid,milliseconds=watch.ElapsedMilliseconds,binding=plan.Binding,errors=plan.Errors});if(!valid)throw new Exception("Real API model scenario failed.");}
    File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="PASS",results=results}));return 0;
   }catch(Exception e){File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="FAIL",error=e.ToString(),results=results}));return 1;}
  }
 }
